import{_ as e,o as i,c as t,a2 as r}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Técnicas y Familiarity","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/characters/techniques.md","filePath":"es/guide/characters/techniques.md"}'),s={name:"es/guide/characters/techniques.md"};function n(c,a,o,l,d,p){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="techniques-familiarity" tabindex="-1">Técnicas y Familiarity <a class="header-anchor" href="#techniques-familiarity" aria-label="Enlace permanente a &quot;Técnicas y Familiarity&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · Disponibilidad no confirmada.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li><a href="/Syrolands-Public/es/guide/characters/skills.html">Skill</a> (habilidad) apoya la ejecución; una <a href="/Syrolands-Public/es/guide/glossary.html#technique">Technique</a> (técnica) aprendida abre una posibilidad concreta.</li><li><a href="/Syrolands-Public/es/guide/characters/familiarity.html">Familiarity</a> (fluidez práctica) es la soltura adquirida, distinta del conocimiento y la preparación.</li><li>Los maestros, el descubrimiento y la reputación apoyan la especialización sin clases permanentes.</li></ul><p><span id="techniques-specializations"></span><span id="skill-is-capability-techniques-are-knowledge"></span><span id="learning-through-the-world"></span><span id="more-to-discover-after-100"></span><span id="practice-and-ready-options"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Elemento</th><th>Qué significa para el jugador</th></tr></thead><tbody><tr><td>Aprender</td><td>Encuentra procedimientos y escuelas mediante maestros, libros, exploración y desafíos adecuados.</td></tr><tr><td>Practicar</td><td>Mejora la fluidez con acciones conocidas; la habilidad por sí sola no concede todas las técnicas.</td></tr><tr><td>Preparar</td><td>Elige opciones de combate o patrones mágicos listos entre los que conoces. Prepararlos no los enseña.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Orientación de Syrolands</th></tr></thead><tbody><tr><td>Los movimientos especiales de armas y Skill Masteries dependen de la época de UO.</td><td>Aprende <a href="/Syrolands-Public/es/guide/combat/special-attacks.html">SAs</a> y otras técnicas mediante el mundo; después practícalas y prepáralas.</td></tr><tr><td>La inversión en habilidades ayuda a definir la configuración del personaje.</td><td>El conocimiento aprendido, la práctica y la reputación también distinguen a personajes con igual habilidad.</td></tr></tbody></table><p>Las reglas de UO varían según la época y el shard. <a href="https://uo.com/wiki/ultima-online-wiki/skills/skill-masteries/" target="_blank" rel="noreferrer">UO oficial: Skill Masteries</a>.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un carpintero hábil podría seguir buscando un maestro de Bowmaking. Aprender el proceso abre un camino hacia convertirse en un fabricante de arcos reconocido; no proporciona automáticamente una ejecución perfecta.</p><h2 id="progression-trade-offs" tabindex="-1">Progresión y contrapartidas <a class="header-anchor" href="#progression-trade-offs" aria-label="Enlace permanente a &quot;Progresión y contrapartidas&quot;">​</a></h2><p>Las técnicas no son todas mutuamente excluyentes. La especialización nace de la inversión, el aprendizaje y la práctica. Los derechos de enseñanza, la reespecialización y las reglas generales de transferencia de conocimientos siguen abiertos.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/characters/familiarity.html">Familiarity y práctica</a> · <a href="/Syrolands-Public/es/guide/characters/skills.html">Habilidades</a> · <a href="/Syrolands-Public/es/guide/combat/special-attacks.html">Ataques especiales</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p>Consulta la especificación de diseño: <a href="/Syrolands-Public/es/game-design/characters/techniques-and-specialization.html">Técnicas y Familiarity</a>.</p>',18)])])}const m=e(s,[["render",n]]);export{u as __pageData,m as default};
